#!/usr/bin/env bash
set -euo pipefail

node - <<'NODE'
const fs = require("node:fs");
const path = require("node:path");
const files = {
  "case-state.md": "# Quality case state\n\nWorkflow: pm:design-critique\nCase: resume\nState: A partial session exists with accepted decisions; source identity must be revalidated before continuing.\nResume revalidation command: node \"$PM_PLUGIN_ROOT/scripts/evals/quality-resume.js\" revalidate design-critique \"$(pwd)\"\n",
  ".pm/quality/input-lock.json": "{\n  \"case_id\": \"design-critique-resume\",\n  \"frozen\": true\n}\n",
  "ui/design-critique/responsive-report.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Quarterly delivery report</title>\n    <style>\n      :root {\n        color-scheme: light;\n        font-family: Inter, ui-sans-serif, system-ui, sans-serif;\n        color: #172033;\n        background: #edf1f7;\n      }\n      * {\n        box-sizing: border-box;\n      }\n      body {\n        margin: 0;\n      }\n      .app-shell {\n        display: grid;\n        grid-template-columns: 240px 1fr;\n        width: 1120px;\n        min-height: 100vh;\n        margin: 0 auto;\n        background: #fff;\n      }\n      nav {\n        padding: 28px 20px;\n        background: #172033;\n        color: #fff;\n      }\n      nav a {\n        display: block;\n        margin: 10px 0;\n        padding: 10px;\n        color: #dbe6ff;\n        text-decoration: none;\n      }\n      main {\n        padding: 32px 40px 64px;\n      }\n      h1 {\n        max-width: 620px;\n        margin: 0 0 8px;\n        font-size: 32px;\n        line-height: 1.15;\n      }\n      .lede {\n        margin: 0 0 28px;\n        color: #536179;\n      }\n      .export-action {\n        position: fixed;\n        top: 24px;\n        right: 18px;\n        z-index: 4;\n        border: 0;\n        border-radius: 8px;\n        padding: 12px 18px;\n        color: #fff;\n        background: #2463eb;\n        font-weight: 700;\n      }\n      button:focus,\n      a:focus {\n        outline: none;\n      }\n      .summary {\n        display: grid;\n        grid-template-columns: repeat(3, 1fr);\n        gap: 16px;\n        margin-bottom: 24px;\n      }\n      .metric {\n        min-height: 112px;\n        padding: 18px;\n        border: 1px solid #d8dfeb;\n        border-radius: 12px;\n      }\n      .metric strong {\n        display: block;\n        margin-top: 12px;\n        font-size: 28px;\n      }\n      .table-frame {\n        border: 1px solid #d8dfeb;\n        border-radius: 12px;\n        overflow: hidden;\n      }\n      table {\n        width: 100%;\n        min-width: 820px;\n        border-collapse: collapse;\n      }\n      th,\n      td {\n        padding: 14px 16px;\n        border-bottom: 1px solid #e7ebf2;\n        text-align: left;\n      }\n      th {\n        background: #f6f8fb;\n      }\n      .icon-button {\n        width: 30px;\n        height: 30px;\n        border: 1px solid #9aa8be;\n        border-radius: 6px;\n        background: #fff;\n      }\n    </style>\n  </head>\n  <body>\n    <div class=\"app-shell\">\n      <nav aria-label=\"Product\">\n        <strong>Relay</strong>\n        <a href=\"#overview\">Overview</a>\n        <a href=\"#delivery\">Delivery</a>\n        <a href=\"#risks\">Risks</a>\n      </nav>\n      <main id=\"overview\">\n        <h1>Quarterly delivery report</h1>\n        <p class=\"lede\">A current view of milestones, confidence, and ownership.</p>\n        <button class=\"export-action\" type=\"button\">Export report</button>\n        <section class=\"summary\" aria-label=\"Delivery summary\">\n          <article class=\"metric\"><span>On track</span><strong>18</strong></article>\n          <article class=\"metric\"><span>At risk</span><strong>4</strong></article>\n          <article class=\"metric\"><span>Blocked</span><strong>2</strong></article>\n        </section>\n        <section id=\"delivery\" aria-labelledby=\"delivery-title\">\n          <h2 id=\"delivery-title\">Milestones</h2>\n          <div class=\"table-frame\">\n            <table>\n              <thead>\n                <tr>\n                  <th>Initiative</th>\n                  <th>Owner</th>\n                  <th>Target</th>\n                  <th>Status</th>\n                  <th>Action</th>\n                </tr>\n              </thead>\n              <tbody>\n                <tr>\n                  <td>Workspace search</td>\n                  <td>Ari</td>\n                  <td>Sep 18</td>\n                  <td>On track</td>\n                  <td><button class=\"icon-button\" aria-label=\"Open workspace search\">↗</button></td>\n                </tr>\n                <tr>\n                  <td>Billing controls</td>\n                  <td>Sam</td>\n                  <td>Sep 25</td>\n                  <td>At risk</td>\n                  <td><button class=\"icon-button\" aria-label=\"Open billing controls\">↗</button></td>\n                </tr>\n                <tr>\n                  <td>Audit export</td>\n                  <td>Noor</td>\n                  <td>Oct 2</td>\n                  <td>Blocked</td>\n                  <td><button class=\"icon-button\" aria-label=\"Open audit export\">↗</button></td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </section>\n      </main>\n    </div>\n  </body>\n</html>\n",
  ".pm/quality/resume-session.json": "{\n  \"workflow\": \"design-critique\",\n  \"completed\": [\n    \"intake\",\n    \"research\"\n  ],\n  \"accepted_decisions\": [\n    \"preserve source identity\"\n  ],\n  \"source_hash\": \"frozen-source\"\n}\n",
  "user-owned-dirt.txt": "local notes — do not overwrite\n",
  ".pm/quality/case-state.json": "{\n  \"workflow\": \"design-critique\",\n  \"case_id\": \"design-critique-resume\",\n  \"case_type\": \"resume\",\n  \"state\": \"A partial session exists with accepted decisions; source identity must be revalidated before continuing.\"\n}\n"
};
for (const [name, content] of Object.entries(files)) {
  fs.mkdirSync(path.dirname(name), { recursive: true });
  fs.writeFileSync(name, content);
}
NODE
git init -q -b main
git config user.email eval@example.com
git config user.name "PM Eval"
git add .
git commit -qm "fixture base"
git init -q --bare .pm/quality/origin.git
git remote add origin "$(pwd)/.pm/quality/origin.git"
git push -q origin main
git --git-dir=.pm/quality/origin.git rev-parse refs/heads/main > .pm/quality/base-main-ref
git switch -qc feature
printf '%s\n' 'design-critique resume change' >> ui/design-critique/responsive-report.html
git add ui/design-critique/responsive-report.html
git commit -qm "fixture feature change"
printf '%s\n' 'user continuation' >> user-owned-dirt.txt
node "$PM_PLUGIN_ROOT/scripts/evals/quality-resume.js" seed design-critique "$(pwd)"
